import * as THREE from './three.module.js';
import {OrbitControls} from './OrbitControls.js';
const $=id=>document.getElementById(id),fmt=(v,n=3)=>Number(v).toFixed(n);
const names=['Left visual 1','Left visual 2','Left attention 1','Left attention 2','Left association 1','Left association 2','Left control 1','Left control 2','Right visual 1','Right visual 2','Right attention 1','Right attention 2','Right association 1','Right association 2','Right control 1','Right control 2'];
const armNames={sham:'No stimulation',fixed:'Calibrated fixed',rate:'Rate feedback',entropy:'Entropy feedback',combined:'Rate + entropy',yoked:'Yoked replay'};
let data,brainData,selected,baseline,personIndex=0,time=0,playing=!matchMedia('(prefers-reduced-motion: reduce)').matches,inflated=false,showConnections=true,region=0,custom=false,renderer,scene,camera,orbit,group,surfaces=[],nodes=[],edges=[],frameClock=performance.now(),lastPaint=0;
let activeOptions={},runMetrics,shamMetrics;
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav,.tab').forEach(e=>e.classList.remove('active'));b.classList.add('active');$(b.dataset.tab).classList.add('active');if(b.dataset.tab==='lab')resize();});
names.forEach((n,i)=>$('region').add(new Option(n,i)));
$('region').onchange=()=>{region=+$('region').value;setRegion()};
function setRegion(){const module=(region%8)>>1;$('region-title').textContent=names[region];$('region-copy').textContent=["An illustrative sensory input population. A binary signal enters here; the model does not decode human intent.","An illustrative attention population within the synthetic network. This is not an empirically validated autism target.","An illustrative association population. The actuator has its strongest modeled influence here; no physical field was fitted.","An illustrative control population contributing to the task readout. These labels explain the model, not a clinical brain map."][module];}
for(let id of ['gain','load'])$(id).oninput=()=>{$(id+'-out').textContent=fmt($(id).value,2);$('run-status').textContent='Parameters changed. Run experiment to apply.';};
$('play').onclick=()=>{playing=!playing;$('play').textContent=playing?'Ⅱ':'▶';$('play').setAttribute('aria-label',playing?'Pause animation':'Play animation')};
$('time').oninput=()=>{time=+$('time').value/20;updateMetrics();drawCharts()};
$('surface').onclick=()=>{inflated=!inflated;$('surface').setAttribute('aria-pressed',inflated);$('surface').textContent=inflated?'Folded cortex':'Inflate cortex';for(let s of surfaces){const arr=brainData[s.userData.side][inflated?'inflated':'vertices'];const pos=s.geometry.attributes.position;for(let i=0;i<arr.length/3;i++){pos.setXYZ(i,arr[i*3],arr[i*3+2],-arr[i*3+1]);}pos.needsUpdate=true;s.geometry.computeVertexNormals();}nodes.forEach(n=>n.visible=!inflated);edges.forEach(e=>e.line.visible=!inflated&&showConnections)};
$('connections').onclick=()=>{showConnections=!showConnections;$('connections').setAttribute('aria-pressed',showConnections);edges.forEach(e=>e.line.visible=showConnections&&!inflated)};
$('home-view').onclick=()=>{camera.position.set(210,110,210);orbit.target.set(0,12,10);orbit.update()};
$('reset').onclick=()=>resetPerson();$('person').onchange=()=>{personIndex=+$('person').value;resetPerson()};
$('strategy').onchange=()=>{const a=$('strategy').value;$('strategy-help').textContent={combined:'Uses measured activity and an individually calibrated entropy response.',rate:'Adjusts feedback from the difference between measured and reference activity.',entropy:'Attempts to match individual reference entropy; weak calibration slopes trigger abstention.',fixed:'Constant input selected on a separate calibration task, with the same amplitude limit.',sham:'The same circuit and disturbance, with no feedback input.',yoked:'Recorded input from another synthetic individual. No live state information.'}[a];loadRecorded()};
function resetPerson(){let p=data.people[personIndex];$('gain').value=p.gain;$('gain-out').textContent=fmt(p.gain,2);$('load').value=p.disturbance;$('load-out').textContent=fmt(p.disturbance,2);$('noise').value='.001';$('noise').selectedIndex=0;$('delay').value=0;$('plasticity').checked=false;$('artifact').checked=false;loadRecorded()}
function metricFromRecorded(arm){return data.example_metrics[personIndex+'_'+arm];}
function loadRecorded(){if(!data)return;let a=$('strategy').value;selected=data.examples[personIndex+'_'+a];baseline=data.examples[personIndex+'_sham'];custom=false;time=0;runMetrics=metricFromRecorded(a);shamMetrics=metricFromRecorded('sham');$('run-status').textContent='Recorded Python run · seed 100 · reference parameters. Change controls and run to explore.';activeOptions={recorded:true,individual:personIndex,strategy:a,seed:100};updateOutcome();updateMetrics();drawCharts();updateEdges()}
$('run').onclick=()=>{if($('strategy').value==='yoked'){resetPerson();$('run-status').textContent='Yoked replay uses the recorded benchmark; choose another strategy for custom parameters.';return;}$('run').disabled=true;$('run-status').textContent='Computing selected strategy and matched no-stimulation control…';const options={gain:+$('gain').value,disturbance:+$('load').value,delay:+$('delay').value,measurement_noise:+$('noise').value,plasticity:$('plasticity').checked?.15:0,artifact:$('artifact').checked?.2:0};activeOptions={...options,individual:personIndex,strategy:$('strategy').value,seed:100,reference_calibration_retained:true};const worker=new Worker('./worker.js',{type:'module'});worker.onmessage=({data:r})=>{if(r.error){$('run-status').textContent=r.error;}else{const down=r=>Object.fromEntries(Object.entries(r).map(([k,v])=>[k,v.filter((_,i)=>i%5===0)]));selected=down(r.selected);baseline=down(r.sham);custom=true;time=0;runMetrics=r.metrics;shamMetrics=r.shamMetrics;$('run-status').textContent='Complete · 100-Hz simulation readout · individual reference calibration retained under changed parameters.';updateOutcome();updateMetrics();drawCharts();}worker.terminate();$('run').disabled=false;};worker.onerror=e=>{$('run-status').textContent='Unable to run: '+e.message;$('run').disabled=false;worker.terminate()};worker.postMessage({person:data.people[personIndex],arm:$('strategy').value,options})};
function updateOutcome(){$('acc').textContent=fmt(runMetrics.accuracy*100,1)+'%';$('base-acc').textContent=fmt(shamMetrics.accuracy*100,1)+'%';$('mse').textContent=fmt(runMetrics.mse);}
function updateMetrics(){if(!selected)return;let i=Math.min(1199,Math.floor(time*20));$('entropy-value').textContent=time<1?'—':fmt(selected.entropy_online[i]);$('rate-value').textContent=fmt(selected.rate[i]);$('u-value').textContent=(selected.u[i]>0?'+':'')+fmt(selected.u[i]);$('node-value').textContent=fmt(selected.E[i][region]);$('weight-value').textContent=fmt(selected.drift[i]*100,2)+'%';$('clock').textContent=fmt(time,1)+' s';$('time').value=i;$('phase').textContent=time<15?'BASELINE':time<30?'CONTEXT A':time<45?'CONTEXT B':'WASHOUT';$('interpretation').textContent=time<15?'Reference state: the same individual provides the calibration target. This is not a population-normalization target.':time<45?'Watch the task outcome as well as entropy. Matching a signal statistic does not guarantee preservation of useful information.':'Input has ended. Remaining weight changes follow the chosen relaxation rule; they are not evidence of lasting human plasticity.';}
function resize(){if(renderer){let e=$('brain');renderer.setSize(e.clientWidth,e.clientHeight);camera.aspect=e.clientWidth/e.clientHeight;camera.updateProjectionMatrix();}drawCharts();}window.addEventListener('resize',resize);
const colorLow=new THREE.Color('#153760'),colorMid=new THREE.Color('#48c4e1'),colorHigh=new THREE.Color('#ffd38b');
function activityColor(v){let z=Math.max(0,Math.min(1,v));return z<.3?colorLow.clone().lerp(colorMid,z/.3):colorMid.clone().lerp(colorHigh,(z-.3)/.7)}
function setupBrain(){const box=$('brain');scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(36,box.clientWidth/box.clientHeight,1,1600);camera.position.set(210,110,210);renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(window.devicePixelRatio,2));renderer.setSize(box.clientWidth,box.clientHeight);box.replaceChildren(renderer.domElement);renderer.setClearColor(0,0);orbit=new OrbitControls(camera,renderer.domElement);orbit.target.set(0,12,10);orbit.enableDamping=true;orbit.dampingFactor=.055;orbit.minDistance=160;orbit.maxDistance=550;orbit.enablePan=false;group=new THREE.Group();scene.add(group);scene.add(new THREE.AmbientLight('#9dc8e8',1.6));let light=new THREE.DirectionalLight('#def9ff',3);light.position.set(-100,150,100);scene.add(light);let rim=new THREE.DirectionalLight('#8264ff',2);rim.position.set(100,30,-100);scene.add(rim);
 for(let side of ['left','right']){let d=brainData[side],a=d.vertices,positions=new Float32Array(a.length);for(let i=0;i<a.length/3;i++){positions[3*i]=a[3*i];positions[3*i+1]=a[3*i+2];positions[3*i+2]=-a[3*i+1];}let geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.BufferAttribute(positions,3));geometry.setIndex(d.faces);geometry.computeVertexNormals();let colors=new Float32Array(a.length);geometry.setAttribute('color',new THREE.BufferAttribute(colors,3));let material=new THREE.MeshPhysicalMaterial({vertexColors:true,roughness:.43,metalness:.25,transparent:true,opacity:.84,side:THREE.DoubleSide,clearcoat:.3});let mesh=new THREE.Mesh(geometry,material);mesh.userData.side=side;group.add(mesh);surfaces.push(mesh);}
 for(let [i,p]of brainData.nodes.entries()){let mesh=new THREE.Mesh(new THREE.SphereGeometry(2.2,12,12),new THREE.MeshBasicMaterial({color:'#b6faff',transparent:true,opacity:.9,depthTest:false}));mesh.position.set(p[0],p[2],-p[1]);mesh.userData.index=i;mesh.renderOrder=4;group.add(mesh);nodes.push(mesh);}updateEdges();
 const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();let down={x:0,y:0};renderer.domElement.addEventListener('pointerdown',e=>down={x:e.clientX,y:e.clientY});renderer.domElement.addEventListener('pointerup',e=>{if(Math.hypot(e.clientX-down.x,e.clientY-down.y)>5)return;const r=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);raycaster.setFromCamera(pointer,camera);const hit=raycaster.intersectObjects(nodes.filter(n=>n.visible));if(hit.length){region=hit[0].object.userData.index;$('region').value=region;setRegion();updateMetrics()}});animate();}
function updateEdges(){if(!group||!data)return;for(let e of edges){group.remove(e.line);e.line.geometry.dispose();e.line.material.dispose();}edges=[];const w=data.people[personIndex].W;for(let i=0;i<16;i++)for(let j=i+1;j<16;j++)if((w[i][j]+w[j][i])/2>.077){let a=nodes[i].position,b=nodes[j].position,mid=a.clone().add(b).multiplyScalar(.5);mid.y+=22;let curve=new THREE.QuadraticBezierCurve3(a,mid,b),g=new THREE.BufferGeometry().setFromPoints(curve.getPoints(30));let line=new THREE.Line(g,new THREE.LineBasicMaterial({color:i<8&&j>=8?'#ac91ff':'#63dfea',transparent:true,opacity:.2,depthTest:false}));line.renderOrder=3;line.visible=showConnections&&!inflated;group.add(line);edges.push({line,i,j});}}
function animate(now=performance.now()){requestAnimationFrame(animate);let delta=Math.min(.1,(now-frameClock)/1000);frameClock=now;if(playing&&$('lab').classList.contains('active'))time=(time+delta*+$('speed').value)%59.95;orbit.update();if(selected){let index=Math.min(1199,Math.floor(time*20));let palette=selected.E[index].map(activityColor);for(let s of surfaces){let regions=brainData[s.userData.side].regions,colors=s.geometry.attributes.color;for(let i=0;i<regions.length;i++){let c=palette[regions[i]];colors.setXYZ(i,c.r,c.g,c.b)}colors.needsUpdate=true;}for(let [i,node]of nodes.entries()){let v=selected.E[index][i];node.scale.setScalar(i===region?1.8:1+v*1.4);node.material.color.set(i===region?'#ffdc99':'#a2fbff');}for(let e of edges)e.line.material.opacity=.06+.4*(selected.E[index][e.i]+selected.E[index][e.j])/2;if(now-lastPaint>120){updateMetrics();drawCharts();lastPaint=now;}}renderer.render(scene,camera)}
function drawChart(id,key,min,max){if(!selected)return;let canvas=$(id),dpr=window.devicePixelRatio||1,w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;if(canvas.width!==w*dpr||canvas.height!==h*dpr){canvas.width=w*dpr;canvas.height=h*dpr;}let c=canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);const left=32,right=w-7,top=12,bottom=h-20;for(let phase=0;phase<4;phase++){c.fillStyle=phase===1?'#6b513c15':phase===2?'#57448518':'#12223735';c.fillRect(left+phase*(right-left)/4,top,(right-left)/4,bottom-top);}c.font='10px Arial';c.fillStyle='#8195b0';c.textAlign='right';for(let k=0;k<3;k++){let y=top+(bottom-top)*k/2;c.fillText(fmt(max-(max-min)*k/2,2),left-6,y+4);c.strokeStyle='#223048';c.lineWidth=.5;c.beginPath();c.moveTo(left,y);c.lineTo(right,y);c.stroke();}for(let[r,color]of [[baseline,'#627792'],[selected,'#5de4ef']]){c.strokeStyle=color;c.lineWidth=1.4;c.beginPath();for(let i=0;i<1200;i++){let x=left+i/1199*(right-left),y=bottom-(r[key][i]-min)/(max-min)*(bottom-top);if(i===0)c.moveTo(x,y);else c.lineTo(x,y)}c.stroke();}let x=left+time/60*(right-left);c.strokeStyle='#f8be6a';c.lineWidth=1;c.beginPath();c.moveTo(x,top);c.lineTo(x,bottom);c.stroke();c.textAlign='center';c.fillStyle='#7a91ad';[0,15,30,45,60].forEach(t=>c.fillText(t+'s',left+t/60*(right-left),h-3));}
function drawCharts(){if(!selected)return;drawChart('rate-chart','rate',0,Math.max(.3,...selected.rate,...baseline.rate)*1.1);drawChart('entropy-chart','entropy_online',0,1);drawChart('input-chart','u',-.65,.65);}
$('export').onclick=()=>{if(!selected)return;let rows=['time_s,mean_activity,observed_mean,permutation_entropy,last_feedback_input,weight_change,sham_mean_activity,'+names.map(n=>n.replaceAll(' ','_')).join(',')];for(let i=0;i<1200;i++)rows.push([i/20,selected.rate[i],selected.observed[i],selected.entropy_online[i],selected.u[i],selected.drift[i],baseline.rate[i],...selected.E[i]].join(','));let blob=new Blob(['# Configuration: '+JSON.stringify(activeOptions)+'\n# Synthetic simulation; 20 Hz display export; not patient data.\n'+rows.join('\n')],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='BBCI_simulation_run.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)};
function renderStudy(){const s=data.study;let primary=s.contrasts.nominal_combined_minus_rate.tracking_mse;$('study-finding').textContent='Adding entropy changed mean input-tracking error by '+fmt(primary[0])+' (95% interval '+fmt(primary[1])+' to '+fmt(primary[2])+') versus rate feedback. Read this as a conditional model result, not a treatment effect.';for(let a of Object.keys(armNames)){let r=s.summary['nominal_'+a],tr=document.createElement('tr');tr.innerHTML='<td>'+armNames[a]+'</td><td>'+fmt(r.tracking_mse[0])+' ['+fmt(r.tracking_mse[1])+', '+fmt(r.tracking_mse[2])+']</td><td>'+fmt(r.accuracy[0]*100,1)+'%</td><td>'+fmt(r.control_energy[0],4)+'</td>';$('results-table').querySelector('tbody').append(tr)}for(let[k,title,copy]of [['delay_2s','Two seconds of added delay','Delayed feedback uses older observations.'],['sensor_noise','Noisier measurement','Sensor noise can change measured entropy without changing the circuit directly.'],['stimulation_artifact','Feedback contaminates its own measurement','A 37-Hz artifact is added to the observation only.'],['plasticity','Activity-dependent coupling','A bounded covariance rule changes weights; a 20-second relaxation governs recovery.']]){let v=s.contrasts[k+'_combined_minus_rate'].tracking_mse;let div=document.createElement('div');div.innerHTML='<div><b>'+title+'</b><p>'+copy+'</p></div><strong>'+fmt(v[0])+'<p>Added-entropy difference in error</p></strong>';$('stress-results').append(div)}}
try{[data,brainData]=await Promise.all([fetch('./web_data.json').then(r=>{if(!r.ok)throw Error('Data could not load');return r.json()}),fetch('./brain.json').then(r=>r.json())]);resetPerson();renderStudy();setRegion();try{setupBrain()}catch(e){$('brain').innerHTML='<p style="padding:80px 30px">3D rendering is unavailable in this browser. The simulation controls, traces, and exports still work.</p>';console.error(e)}$('play').textContent=playing?'Ⅱ':'▶';}catch(e){$('run-status').textContent='Unable to load research data: '+e.message;$('brain-loading').textContent='Research data could not load.';}
